// search.query: Search the names of the inventory of a connection
// Generated by `pnpm nx g @app/generators:action search.query`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema, ObjectKeySchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  FILTER_TEXT_MAX,
  FreshnessSchema,
  SEARCH_RESULT_MAX,
} from './explorer-types.ts';

/** The kinds whose names can be searched (a kind joins when the index holds its names). */
export const SEARCH_KINDS = ['queues', 'exchanges'] as const;
export type SearchKind = (typeof SEARCH_KINDS)[number];

/** How a name matched: the whole name, the start of it, or a part of it (case-insensitive). */
export const SEARCH_RANKS = ['exact', 'prefix', 'substring'] as const;

export const SearchQueryInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  /** A plain text, matched case-insensitively against names; never a pattern. */
  text: z.string().min(1).max(FILTER_TEXT_MAX),
  /** Default: every kind in SEARCH_KINDS. */
  kinds: z
    .array(z.enum(SEARCH_KINDS))
    .min(1)
    .max(SEARCH_KINDS.length)
    .optional(),
});

export const SearchResultSchema = z.strictObject({
  kind: z.enum(SEARCH_KINDS),
  key: ObjectKeySchema,
  vhost: z.string(),
  name: z.string(),
  rank: z.enum(SEARCH_RANKS),
});

export const SearchQueryOutputSchema = z.strictObject({
  /** Best first: exact, then prefix, then substring; shorter names first; ties by key. */
  results: z.array(SearchResultSchema).max(SEARCH_RESULT_MAX),
  /** Names that matched, of which `results` shows the best. */
  matched: z.number().int().nonnegative(),
  /** More names matched than `results` holds. */
  truncated: z.boolean(),
  /** What the index said about itself, over the kinds that were searched. */
  freshness: FreshnessSchema,
});

export const searchQuery = defineAction({
  id: 'search.query',
  kind: 'query',
  summary: 'Search the names of the inventory of a connection',
  input: SearchQueryInputSchema,
  output: SearchQueryOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid }),
  http: { method: 'POST', path: '/connections/{cid}/search' },
  since: '1.0',
});
